/**
 * implements a head filter on the input stream
 */
private String headFilter(String line) {
    linesRead++;
    if (skip > 0) {
        if ((linesRead - 1) < skip) {
            return null;
        }
    }
    if (lines > 0) {
        if (linesRead > (lines + skip)) {
            eof = true;
            return null;
        }
    }
    return line;
}

