                                stringResult += "'" + itemVal + "'";
                            } else {
                                stringResult += itemVal;
                            }
                            if (k != valList.size() - 1) {
                                stringResult += ",";
                            }
                        }
                        LovValue defValue = new LovValue();
                        defValue.setValue(stringResult);
                        defValue.setDescription(stringResult);
                        parameterValueList.add(defValue);
