                            defValue.setValue(itemVal);
                            defValue.setDescription(itemDescr != null ? itemDescr : itemVal);
                            parameterValueList.add(defValue);
                        }
                    }
                    parameterAsMap.put("parameterValue", parameterValueList);
                }
            }
