        if (result == 0.0 && !(this instanceof SubtractEvalClass)) {
            return NumberEval.ZERO;
        }
        if (Double.isNaN(result) || Double.isInfinite(result)) {
            return ErrorEval.NUM_ERROR;
        }
    } catch (EvaluationException e) {
        return e.getErrorEval();
